function TempInput({ label, value, onChange }) {
  return (
    <label style={{ display: 'block', marginBottom: 8 }}>
      {label}: <input value={value} onChange={e => onChange(e.target.value)} />
    </label>
  );
}

function App() {
  const [celsius, setCelsius] = useState('0');
  const fromC = c => (c === '' ? '' : String(Number(c) * 9 / 5 + 32));
  const fromF = f => (f === '' ? '' : String((Number(f) - 32) * 5 / 9));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <TempInput label="Celsius" value={celsius} onChange={setCelsius} />
      <TempInput label="Fahrenheit" value={fromC(celsius)} onChange={f => setCelsius(fromF(f))} />
    </div>
  );
}

