function SearchBar({ query, onChange }) {
  return <input value={query} onChange={e => onChange(e.target.value)} />;
}

function Badge({ count }) {
  return <p>Showing {count} results</p>;
}

function App() {
  const all = ['apple', 'banana', 'cherry'];
  const [query, setQuery] = useState('');
  const visible = all.filter(i => i.includes(query.toLowerCase()));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <SearchBar query={query} onChange={setQuery} />
      <Badge count={visible.length} />
      <ul>{visible.map(i => <li key={i}>{i}</li>)}</ul>
    </div>
  );
}

function NumberInput({ value, onChange }) {
  return (
    <input
      type="number"
      value={value}
      onChange={e => onChange(Number(e.target.value))}
    />
  );
}

function Doubler({ value }) {
  return <p>Double: {value * 2}</p>;
}

function App() {
  const [num, setNum] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <NumberInput value={num} onChange={setNum} />
      <Doubler value={num} />
    </div>
  );
}
